## main.tf
```hcl
data "aws_caller_identity" "current" {}
data "aws_partition" "current" {}

locals {
  name = "${var.project}-${var.env}-invoices"
  tags = {
    project       = var.project
    env           = var.env
    owner         = var.owner
    "cost-center" = var.cost_center
    data-class    = "pii"
    ticket        = "TCK-60"
  }
  account_root = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
}

# ---------- KMS CMK riêng cho hoá đơn ----------
data "aws_iam_policy_document" "kms" {
  # Quản trị khoá (không có Decrypt/Encrypt) cho pipeline
  statement {
    sid       = "KeyAdminNoCrypto"
    principals { type = "AWS", identifiers = [var.pipeline_principal_arn] }
    actions   = ["kms:Describe*", "kms:Get*", "kms:List*", "kms:Put*", "kms:Update*", "kms:Enable*", "kms:Disable*", "kms:TagResource", "kms:UntagResource", "kms:ScheduleKeyDeletion", "kms:CancelKeyDeletion", "kms:CreateAlias", "kms:DeleteAlias"]
    resources = ["*"]
  }
  # Chỉ payment-service dùng khoá cho mã hoá/giải mã, và chỉ qua S3
  statement {
    sid       = "ServiceUseViaS3"
    principals { type = "AWS", identifiers = [var.service_principal_arn] }
    actions   = ["kms:Decrypt", "kms:GenerateDataKey", "kms:Encrypt", "kms:DescribeKey"]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${data.aws_region.current.name}.amazonaws.com"]
    }
  }
  # Chặn cứng: không principal nào khác được giải mã, kể cả admin trong tài khoản
  statement {
    sid       = "DenyCryptoToOthers"
    effect    = "Deny"
    principals { type = "AWS", identifiers = ["*"] }
    actions   = ["kms:Decrypt", "kms:ReEncrypt*", "kms:GenerateDataKey*", "kms:Encrypt"]
    resources = ["*"]
    condition {
      test     = "ArnNotEquals"
      variable = "aws:PrincipalArn"
      values   = [var.service_principal_arn]
    }
  }
  # Giữ root của tài khoản để khoá không bị mồ côi (quản trị, không crypto: Deny ở trên vẫn thắng)
  statement {
    sid       = "AccountRootAdmin"
    principals { type = "AWS", identifiers = [local.account_root] }
    actions   = ["kms:Describe*", "kms:Get*", "kms:List*", "kms:PutKeyPolicy"]
    resources = ["*"]
  }
}

data "aws_region" "current" {}

resource "aws_kms_key" "invoices" {
  description             = "CMK hoá đơn PDF ${local.name}"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.kms.json
  tags                    = local.tags
  lifecycle { prevent_destroy = true }
}

resource "aws_kms_alias" "invoices" {
  name          = "alias/${local.name}"
  target_key_id = aws_kms_key.invoices.key_id
}

# ---------- Bucket log truy cập ----------
resource "aws_s3_bucket" "logs" {
  bucket = "${local.name}-access-logs"
  tags   = merge(local.tags, { data-class = "internal" })
}
resource "aws_s3_bucket_public_access_block" "logs" {
  bucket                  = aws_s3_bucket.logs.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}
resource "aws_s3_bucket_server_side_encryption_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id
  rule { apply_server_side_encryption_by_default { sse_algorithm = "AES256" } } # S3 server access logging không hỗ trợ đích SSE-KMS
}
resource "aws_s3_bucket_ownership_controls" "logs" {
  bucket = aws_s3_bucket.logs.id
  rule { object_ownership = "BucketOwnerEnforced" }
}
resource "aws_s3_bucket_lifecycle_configuration" "logs" {
  bucket = aws_s3_bucket.logs.id
  rule {
    id     = "expire-logs"
    status = "Enabled"
    filter {}
    expiration { days = var.log_retention_days }
  }
}
resource "aws_s3_bucket_policy" "logs" {
  bucket = aws_s3_bucket.logs.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "S3ServerAccessLogs"
        Effect    = "Allow"
        Principal = { Service = "logging.s3.amazonaws.com" }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.logs.arn}/invoices/*"
        Condition = {
          StringEquals = { "aws:SourceAccount" = data.aws_caller_identity.current.account_id }
          ArnLike      = { "aws:SourceArn" = aws_s3_bucket.invoices.arn }
        }
      },
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource  = [aws_s3_bucket.logs.arn, "${aws_s3_bucket.logs.arn}/*"]
        Condition = { Bool = { "aws:SecureTransport" = "false" } }
      }
    ]
  })
}

# ---------- Bucket hoá đơn ----------
resource "aws_s3_bucket" "invoices" {
  bucket = local.name
  tags   = local.tags
  lifecycle { prevent_destroy = true }
}
resource "aws_s3_bucket_public_access_block" "invoices" {
  bucket                  = aws_s3_bucket.invoices.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}
resource "aws_s3_bucket_ownership_controls" "invoices" {
  bucket = aws_s3_bucket.invoices.id
  rule { object_ownership = "BucketOwnerEnforced" }
}
resource "aws_s3_bucket_versioning" "invoices" {
  bucket = aws_s3_bucket.invoices.id
  versioning_configuration { status = "Enabled" }
}
resource "aws_s3_bucket_server_side_encryption_configuration" "invoices" {
  bucket = aws_s3_bucket.invoices.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.invoices.arn
    }
    bucket_key_enabled = true
  }
}
resource "aws_s3_bucket_logging" "invoices" {
  bucket        = aws_s3_bucket.invoices.id
  target_bucket = aws_s3_bucket.logs.id
  target_prefix = "invoices/"
}
resource "aws_s3_bucket_lifecycle_configuration" "invoices" {
  bucket = aws_s3_bucket.invoices.id
  rule {
    id     = "retention"
    status = "Enabled"
    filter { prefix = "invoices/" }
    expiration { days = var.retention_days }
    noncurrent_version_expiration { noncurrent_days = var.noncurrent_version_days }
    abort_incomplete_multipart_upload { days_after_initiation = 7 }
  }
}

locals {
  data_actions = ["s3:GetObject", "s3:GetObjectVersion", "s3:PutObject", "s3:DeleteObject", "s3:DeleteObjectVersion", "s3:RestoreObject", "s3:GetObjectAttributes", "s3:ListBucket", "s3:ListBucketVersions"]
}

resource "aws_s3_bucket_policy" "invoices" {
  bucket     = aws_s3_bucket.invoices.id
  depends_on = [aws_s3_bucket_public_access_block.invoices]
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource  = [aws_s3_bucket.invoices.arn, "${aws_s3_bucket.invoices.arn}/*"]
        Condition = { Bool = { "aws:SecureTransport" = "false" } }
      },
      {
        Sid       = "DenyDataAccessExceptService"
        Effect    = "Deny"
        Principal = "*"
        Action    = local.data_actions
        Resource  = [aws_s3_bucket.invoices.arn, "${aws_s3_bucket.invoices.arn}/*"]
        Condition = { ArnNotEquals = { "aws:PrincipalArn" = var.service_principal_arn } }
      },
      {
        Sid       = "DenyNonKmsUpload"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.invoices.arn}/*"
        Condition = { StringNotEqualsIfExists = { "s3:x-amz-server-side-encryption" = "aws:kms" } }
      },
      {
        Sid       = "DenyWrongKmsKey"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.invoices.arn}/*"
        Condition = { StringNotEqualsIfExists = { "s3:x-amz-server-side-encryption-aws-kms-key-id" = aws_kms_key.invoices.arn } }
      }
    ]
  })
}

# ---------- Quyền tối thiểu cho payment-service ----------
data "aws_iam_policy_document" "service" {
  statement {
    sid       = "InvoiceObjects"
    actions   = ["s3:GetObject", "s3:GetObjectVersion", "s3:PutObject"]
    resources = ["${aws_s3_bucket.invoices.arn}/invoices/*"]
  }
  statement {
    sid       = "ListInvoicePrefix"
    actions   = ["s3:ListBucket"]
    resources = [aws_s3_bucket.invoices.arn]
    condition {
      test     = "StringLike"
      variable = "s3:prefix"
      values   = ["invoices/*"]
    }
  }
  statement {
    sid       = "UseInvoiceKey"
    actions   = ["kms:Decrypt", "kms:GenerateDataKey"]
    resources = [aws_kms_key.invoices.arn]
  }
}

resource "aws_iam_policy" "service" {
  name   = "${local.name}-payment-service-rw"
  policy = data.aws_iam_policy_document.service.json
  tags   = local.tags
}

resource "aws_iam_role_policy_attachment" "service" {
  role       = var.service_role_name
  policy_arn = aws_iam_policy.service.arn
}
```
Ghi chú thiết kế: payment-service không có `s3:DeleteObject`. Hoá đơn chỉ hết hạn theo lifecycle. Nếu dịch vụ cần xoá thì phải mở ticket riêng.

