## tests/invoice_bucket.tftest.hcl (tofu test, mock provider)
```hcl
mock_provider "aws" {}
variables {
  project = "p1"
  env = "dev"
  owner = "o"
  cost_center = "cc"
  service_role_name = "svc"
  service_principal_arn = "arn:aws:iam::111111111111:role/svc"
  pipeline_principal_arn = "arn:aws:iam::111111111111:role/ci"
  retention_days = 3650
}
run "public_access_blocked" {
  command = plan
  assert {
    condition = alltrue([aws_s3_bucket_public_access_block.invoices.block_public_acls, aws_s3_bucket_public_access_block.invoices.block_public_policy, aws_s3_bucket_public_access_block.invoices.ignore_public_acls, aws_s3_bucket_public_access_block.invoices.restrict_public_buckets])
    error_message = "Bucket hoá đơn phải chặn public."
  }
}
run "kms_encryption_and_rotation" {
  command = plan
  assert {
    condition = one(one(aws_s3_bucket_server_side_encryption_configuration.invoices.rule).apply_server_side_encryption_by_default).sse_algorithm == "aws:kms"
    error_message = "Phải SSE-KMS."
  }
  assert {
    condition = aws_kms_key.invoices.enable_key_rotation
    error_message = "CMK phải xoay vòng."
  }
}
run "only_service_reads" {
  command = plan
  assert {
    condition = strcontains(aws_s3_bucket_policy.invoices.policy, "DenyDataAccessExceptService") && strcontains(aws_s3_bucket_policy.invoices.policy, var.service_principal_arn)
    error_message = "Bucket policy phải deny mọi principal ngoài payment-service."
